      IF FOUND AND st_source.source_revision=st_revision AND (st_source.superseded_reason=''staff_failed_director_validation_retry'' OR (st_source.id IN(''d460a7be-a3a2-4ad8-9d3b-d2e929f2947e''::uuid,''f4f7185e-4aae-4edd-ac24-65f8dcfa36f5''::uuid) AND st_source.master_session_id=''44078c5f-7001-4129-9506-e2f34e68c8ac''::uuid AND st_source.superseded_reason=''staff_preprovider_request_retry''))
       AND st_source.consumed_message_id IS NULL AND mission_generic_owner.role_source_released_v4(st_source.id) THEN
       st_released:=true;st_state:=''released'';st_recovery:=st_work.id;
